def drive(me, enemy, arena):
    b = bearing_to(enemy.x, enemy.y)
    r = sqrt(me.x * me.x + me.y * me.y)
    if r > 5.2:
        bc = bearing_to(0, 0)
        if r > 5.8:
            b = bc
        elif abs(b) > 90:
            b = bc
    turn = b / 40.0
    if turn > 1.0:
        turn = 1.0
    if turn < -1.0:
        turn = -1.0
    throttle = 1.0 - abs(b) / 120.0
    if throttle < 0.0:
        throttle = 0.0
    if throttle > 1.0:
        throttle = 1.0
    dist = distance_to(enemy.x, enemy.y)
    if dist < 2.0:
        throttle = 1.0
    if me.inverted:
        turn = -turn
    left = throttle - turn
    right = throttle + turn
    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0
    return (left, right)

