def drive(me, enemy, arena):
    # If we are on our side or end, we cannot drive.
    if me.on_side:
        return None

    # Calculate relative state
    bearing = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # Strategy: Maintain a head-on orientation to minimize side-impacts 
    # from the opponent's lethal horizontal spinner and maximize the 
    # effectiveness of our front wedge and vertical spinner.

    # We are invertible, so if we are upside down, we can still drive 
    # and use our vertical spinner, although our wedge is disabled.

    if abs(bearing) < 8:
        # Aligned: Charge forward to engage the opponent head-on.
        return (1.0, 1.0)
    elif bearing > 0:
        # Enemy is to the left: Turn left while closing in.
        # Use a lower forward speed when close to avoid overshooting.
        speed = 0.6 if dist > 1.5 else 0.2
        return (speed, 1.0)
    else:
        # Enemy is to the right: Turn right while closing in.
        speed = 0.6 if dist > 1.5 else 0.2
        return (1.0, speed)

