def drive(me, enemy, arena):
    if me.on_side:
        return (0, 0)
    if distance_to(enemy.x, enemy.y) > 2.2:
        h = radians(enemy.heading)
        lx = -sin(h)
        ly = cos(h)
        dx = me.x - enemy.x
        dy = me.y - enemy.y
        dot = dx * lx + dy * ly
        if dot >= 0:
            sign = 1.0
        else:
            sign = -1.0
        tx = enemy.x + sign * lx * 1.2
        ty = enemy.y + sign * ly * 1.2
    else:
        tx = enemy.x
        ty = enemy.y
    r = sqrt(me.x * me.x + me.y * me.y)
    if r > 5.5:
        tx = 0.0
        ty = 0.0
    b = bearing_to(tx, ty)
    turn = b / 25.0
    if turn > 1.0:
        turn = 1.0
    if turn < -1.0:
        turn = -1.0
    d = distance_to(tx, ty)
    throttle = 1.0
    if abs(b) > 60.0:
        throttle = 0.2
    elif abs(b) > 30.0:
        throttle = 0.6
    if d < 1.0:
        throttle = 1.0
    if me.inverted:
        turn = -turn
    left = throttle - turn
    right = throttle + turn
    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0
    return (left, right)

